function loadDemo(){if(!confirm('オリジナルの短いデモ曲を読み込みます。現在の曲を置き換えるため、必要なら先にプロジェクトZIPを保存してください。'))return;stop();const secs=['イントロ','Aメロ','サビ','アウトロ'].map(x=>makeSection(x,4,4));let at=0;for(const sec of secs){sec.startBeat=at;at+=sec.lengthBeats;sec.root=0;sec.mode='major';sec.chords=[{degree:1,alter:0,quality:'maj',beats:4},{degree:6,alter:0,quality:'m',beats:4},{degree:4,alter:0,quality:'maj',beats:4},{degree:5,alter:0,quality:'maj',beats:4}];}const tracks=['piano','guitar','bass','drums'].map(t=>makeTrack(t)),guide=makeTrack('guide');for(let i=0;i<2;i++){const sec=secs[i+1];const motif=[64,67,69,67,64,62,60,64];for(let k=0;k<8;k++){guide.notes.push({id:uid(),start:sec.startBeat+k*2,duration:1.7,pitch:motif[k]+(i===1?5:0),velocity:83});}}tracks.push(guide);st={...blank(),title:'デモ — 夜明けの輪郭',sections:secs,tracks,selectedSectionId:secs[0].id,selectedTrackId:tracks[0].id,bpm:120,beats:4};audioFiles.clear();audioBuffers.clear();selectedNotes.clear();history=[];histIndex=-1;synthesizeArrangement(true);syncControls();render();toast('オリジナルのデモ曲を準備しました。再生ボタンでピアノ・ギター・ベース・ドラムを試せます。',6500);}
function addTrack(type){if(st.tracks.length>=18)return toast('トラックは18本までです。');const t=makeTrack(type);st.tracks.push(t);st.selectedTrackId=t.id;selectedNotes.clear();checkpoint();render();}
function removeTrack(){const t=findTrack();if(!t||isGuide(t))return;if(st.tracks.length<=1)return toast('トラックは最低1つ必要です。');if(!confirm(`「${t.name}」とその音符・音声クリップを削除しますか？（直後なら戻すボタンで取り消せます）`))return;st.tracks=st.tracks.filter(x=>x.id!==t.id);st.clips=st.clips.filter(c=>c.trackId!==t.id);st.selectedTrackId=st.tracks[0].id;selectedNotes.clear();checkpoint();render();}
function buildPeaks(buffer,count=180){const channel=buffer.getChannelData(0),out=[];for(let i=0;i<count;i++){const from=Math.floor(i*channel.length/count),to=Math.min(channel.length,Math.floor((i+1)*channel.length/count));let peak=0;for(let j=from;j<to;j+=Math.max(1,Math.floor((to-from)/60)))peak=Math.max(peak,Math.abs(channel[j]));out.push(Number(peak.toFixed(3)));}return out;}
async function getCtx(){if(!AC)throw Error('このブラウザーはWeb Audioに対応していません');if(!ctx)ctx=new AC();if(ctx.state==='suspended')await ctx.resume();return ctx;}
async function decodeAndCache(id,blob){if(!AC)throw Error('このブラウザーはWeb Audioに対応していません');if(!ctx)ctx=new AC();const buffer=await ctx.decodeAudioData(await blob.arrayBuffer());audioBuffers.set(id,buffer);return buffer;}
async function importAudio(file,kind){if(!file)return;try{if(st.tracks.length>=18)throw Error('トラックは18本までです');if(file.size>MAX_AUDIO_SIZE)throw Error('音声ファイルは80MBまでです');const id=uid(),buffer=await decodeAndCache(id,file);if(buffer.duration>MAX_SEC)throw Error('音声は6分以内にしてください');const type=kind==='voice'?'voice':'audio',track=makeTrack(type,kind==='voice'?'ボーカル':file.name.replace(/\.[^.]+$/,''));st.tracks.push(track);const clip={id,trackId:track.id,name:file.name,startBeat:kind==='voice'?0:st.playheadBeat,peaks:buildPeaks(buffer)};st.clips.push(clip);audioFiles.set(id,file);st.selectedTrackId=track.id;selectedNotes.clear();checkpoint();render();toast(`${file.name} を${kind==='voice'?'曲の先頭':'現在の再生位置'}に配置しました。`);}catch(e){console.error(e);toast('取り込みに失敗：'+e.message,6500);}}
function renderClipEditor(t){const out=$('rollMessage');out.replaceChildren();const text=document.createElement('p');text.textContent='このトラックでは音声クリップの開始位置を調整できます。歌声WAVは曲の先頭に置くのが基本です。';out.append(text);for(const c of st.clips.filter(c=>c.trackId===t.id)){const row=document.createElement('div');row.className='structure-actions';row.style.margin='12px 0';const name=document.createElement('strong');name.textContent=`${c.name} · 開始 ${c.startBeat.toFixed(2)}拍 (${stamp(c.startBeat*60/st.bpm)})`;row.append(name);for(const [label,delta] of [['← 1/4拍',-.25],['→ 1/4拍',.25],['← 1拍',-1],['→ 1拍',1]]){const b=document.createElement('button');b.className='btn ghost small';b.textContent=label;b.onclick=()=>{c.startBeat=clamp(c.startBeat+delta,0,MAX_BEATS);checkpoint();render();};row.append(b);}const del=document.createElement('button');del.className='btn ghost small danger';del.textContent='この音声を外す';del.onclick=()=>{if(!confirm(`「${c.name}」を曲から外しますか？`))return;st.clips=st.clips.filter(x=>x.id!==c.id);checkpoint();render();};row.append(del);out.append(row);}}
