function pause(){if(!playback)return;const p=playback;st.playheadBeat=clamp((p.origin+Math.max(0,p.c.currentTime-p.started))*st.bpm/60,0,totalBeats());finishPlayback();render();}
function finishPlayback(){if(!playback)return;clearInterval(playback.timer);cancelAnimationFrame(playback.raf);for(const node of playback.nodes)try{node.stop()}catch{}playback=null;sessionToken++;$('playBtn').textContent='▶ 再生';scheduleSave();}
function stop(reset=true){finishPlayback();if(reset)st.playheadBeat=0;renderTime();renderArrangement();renderRoll();}
async function renderOffline(mode,bits=24){if(!st.tracks.some(t=>includedTrack(t,mode)&&(t.notes?.length||st.clips.some(c=>c.trackId===t.id&&audioBuffers.has(c.id)))))throw Error('この書き出しに含める音がありません。先に伴奏や歌声を追加してください');if(!OfflineAC)throw Error('このブラウザーはOfflineAudioContext非対応です');const dur=seconds();if(dur>MAX_SEC+.005)throw Error('書き出しは6分までです。曲を短くしてください');if(dur<=0)throw Error('曲の長さが0です');$('audioEngineStatus').textContent='音声を書き出し中…';await new Promise(r=>setTimeout(r,25));const rate=mode==='voice'?32000:44100,c=new OfflineAC(2,Math.ceil((dur+.35)*rate),rate),buses=buildMixGraph(c,mode);for(const {track,note,sec} of createEvents(mode)){const bus=buses.get(track.id);if(bus&&sec<=dur){scheduleMelodic(c,bus,track.type,note,Math.max(0,sec));}}for(const clip of st.clips){const bus=buses.get(clip.trackId);if(bus)scheduleSample(c,bus,clip,0,0);}const result=await c.startRendering();$('audioEngineStatus').textContent='書き出し完了';return waveEncode(result,bits,st.normalize);}
async function exportWave(mode){const btn=mode==='instrument'?'exportInstrumentBtn':'exportFinalBtn';$(btn).disabled=true;try{const blob=await renderOffline(mode,24);download(blob,fileName()+(mode==='instrument'?'-Instrumental-24bit.wav':'-Final-Mix-24bit.wav'));toast(mode==='instrument'?'伴奏だけのWAVを保存しました。':'完成曲のWAVを保存しました。');}catch(e){console.error(e);toast('書き出しに失敗：'+e.message,7000);}finally{$(btn).disabled=false;}}
async function exportVoice(){const btn=$('exportVoiceBtn');btn.disabled=true;try{if(st.sections.length>40)throw Error('Voiceのブロック上限は40です');if(st.sections.some(s=>Math.ceil(s.lengthBeats/st.beats)>48))throw Error('Voiceの1ブロックは48小節までです');const wav=await renderOffline('voice',16),raw=new Uint8Array(await wav.arrayBuffer());if(raw.length>200*1024*1024)throw Error('ガイド音声は200MBまでです');const sections=st.sections.map(s=>({name:s.name,lyrics:s.lyrics||'',reading:'',startBeat:s.startBeat,bars:Math.max(1,Math.ceil(s.lengthBeats/st.beats)),lengthBeats:s.lengthBeats,gapBeats:0,root:s.root||0,mode:s.mode||'major',notes:[],chords:s.chords||[],harmonies:s.harmonies||[]}));const bridge={format:'melody-voice-bridge',version:1,source:'Music Atelier',title:st.title,bpm:st.bpm,beats:st.beats,audioFile:'guide.wav',includesChords:true,guideSeconds:seconds(),sections};const zip=zipStore([['bridge.json',JSON.stringify(bridge)],['guide.wav',raw],['music-project.json',JSON.stringify(serial())]]);if(zip.size>230*1024*1024)throw Error('Voice連携ZIPの上限は230MBです');download(zip,fileName()+'-Voice連携.zip');toast('Voice Atelier用ZIPを保存しました。「Melody連携ZIPを取り込む」で開いてください。',6800);}catch(e){console.error(e);toast('Voice連携ZIP作成失敗：'+e.message,7400);}finally{btn.disabled=false;}}

let automationSelected=-1,automationDragging=false;
function autoView(){const zoom=Number($('autoZoom')?.value||1),span=Math.max(1,totalBeats()/zoom),start=clamp(Number($('autoStart')?.value||0),0,Math.max(0,totalBeats()-span));return {span,start};}
const autoLimits={volume:[0,150],pan:[-100,100],reverb:[0,100]};
function autoPoints(){const t=findTrack(),key=$('automationTarget').value;if(!t)return [];t.automation=t.automation||{};return t.automation[key]=t.automation[key]||[];}
function renderAutomation(){
 const t=findTrack();if(!t)return;
 for(const [field,id,suffix] of [['compression','mixCompression','%'],['attack','mixAttack','ms'],['release','mixRelease','ms']]){
  $(id).value=t[field]??(field==='compression'?0:field==='attack'?10:180);$(id+'Val').textContent=$(id).value+suffix;
 }
 const cvs=$('automationCanvas'),g=cvs.getContext('2d'),w=cvs.width,h=cvs.height,key=$('automationTarget').value,[min,max]=autoLimits[key],pts=autoPoints();
 g.clearRect(0,0,w,h);g.fillStyle='#101d29';g.fillRect(0,0,w,h);
 for(let i=0;i<=8;i++){const {span,start}=autoView();const x=32+i*(w-48)/8;g.strokeStyle='#304555';g.beginPath();g.moveTo(x,8);g.lineTo(x,h-24);g.stroke();g.fillStyle='#a9bdc9';g.font='12px sans-serif';g.fillText(String(Math.round(start+span*i/8)),x-8,h-7);}
 for(let i=0;i<=4;i++){const y=8+i*(h-32)/4;g.strokeStyle='#304555';g.beginPath();g.moveTo(32,y);g.lineTo(w-16,y);g.stroke();g.fillStyle='#a9bdc9';g.fillText(String(Math.round(max-(max-min)*i/4)),2,y+4);}
 const x=b=>32+clamp((b-autoView().start)/autoView().span,0,1)*(w-48),y=v=>8+(max-clamp(v,min,max))/(max-min)*(h-32);
 const base=clamp(t[key],min,max);
 g.strokeStyle='#75dacc';g.lineWidth=2.5;g.beginPath();g.moveTo(x(0),y(pts.length&&pts[0].beat===0?pts[0].value:base));
 pts.forEach(pt=>g.lineTo(x(pt.beat),y(pt.value)));g.lineTo(x(autoView().start+autoView().span),y(pts.length?pts[pts.length-1].value:base));g.stroke();
 pts.forEach((pt,i)=>{g.beginPath();g.arc(x(pt.beat),y(pt.value),i===automationSelected?7:5,0,Math.PI*2);g.fillStyle=i===automationSelected?'#ffd99a':'#7ae3d1';g.fill();});
 $('automationInfo').textContent=`${t.name} / ${key}：${pts.length}点。タップで追加、点をドラッグで移動。`;
}
function autoPos(e){const r=$('automationCanvas').getBoundingClientRect(),x=(e.clientX-r.left)*800/r.width,y=(e.clientY-r.top)*160/r.height,[lo,hi]=autoLimits[$('automationTarget').value];return {beat:Math.round((autoView().start+clamp((x-32)/752,0,1)*autoView().span)*8)/8,value:Math.round(clamp(hi-(y-8)/128*(hi-lo),lo,hi)),x,y};}
function initAutomation(){
 const cvs=$('automationCanvas');
 $('autoZoom').oninput=()=>renderAutomation();
 $('autoStart').oninput=()=>renderAutomation();
 $('autoPrev').onclick=()=>{$('autoStart').value=Math.max(0,autoView().start-autoView().span*.75);renderAutomation();};
 $('autoNext').onclick=()=>{$('autoStart').value=Math.min(totalBeats()-autoView().span,autoView().start+autoView().span*.75);renderAutomation();};
 $('automationTarget').onchange=()=>{automationSelected=-1;renderAutomation();};
 $('automationAdd').onclick=()=>{const pts=autoPoints(),key=$('automationTarget').value,[lo,hi]=autoLimits[key],beat=clamp(Number($('automationBeat').value),0,totalBeats()),value=clamp(Number($('automationValue').value),lo,hi);pts.push({beat,value});pts.sort((a,b)=>a.beat-b.beat);automationSelected=pts.findIndex(p=>p.beat===beat&&p.value===value);checkpoint();renderAutomation();};
 $('automationRemove').onclick=()=>{const pts=autoPoints();if(automationSelected>=0&&automationSelected<pts.length){pts.splice(automationSelected,1);automationSelected=-1;checkpoint();renderAutomation();}};
 $('automationClear').onclick=()=>{autoPoints().length=0;automationSelected=-1;checkpoint();renderAutomation();};
 cvs.addEventListener('pointerdown',e=>{const pts=autoPoints(),p=autoPos(e),r=cvs.getBoundingClientRect();let closest=-1,dist=20;pts.forEach((pt,i)=>{const dx=(32+(pt.beat-autoView().start)/autoView().span*752-p.x)*r.width/800,dy=(8+(autoLimits[$('automationTarget').value][1]-pt.value)/(autoLimits[$('automationTarget').value][1]-autoLimits[$('automationTarget').value][0])*128-p.y)*r.height/160,d=Math.hypot(dx,dy);if(d<dist){dist=d;closest=i;}});if(closest<0){pts.push({beat:p.beat,value:p.value});closest=pts.length-1;}automationSelected=closest;automationDragging=true;cvs.setPointerCapture(e.pointerId);renderAutomation();});
 cvs.addEventListener('pointermove',e=>{if(!automationDragging)return;const pt=autoPoints()[automationSelected];if(!pt)return;Object.assign(pt,autoPos(e));$('automationBeat').value=pt.beat;$('automationValue').value=pt.value;renderAutomation();});
 const end=()=>{if(!automationDragging)return;automationDragging=false;autoPoints().sort((a,b)=>a.beat-b.beat);automationSelected=-1;checkpoint();renderAutomation();};
 cvs.addEventListener('pointerup',end);cvs.addEventListener('pointercancel',end);
 for(const field of ['compression','attack','release']){const id='mix'+field[0].toUpperCase()+field.slice(1);$(id).oninput=()=>{const t=findTrack();if(!t)return;t[field]=Number($(id).value);$(id+'Val').textContent=t[field]+(field==='compression'?'%':'ms');};$(id).onchange=checkpoint;}
}


// Local, offline audio-to-MIDI-style note conversion. Designed for isolated monophonic sources.
let transcriptionPending=null;
function transcribeMono(samples,rate,kind,sensitivity){
 const hop=256,win=2048,step=rate/11025,signal=new Float32Array(Math.ceil(samples.length/step));
 for(let i=0;i<signal.length;i++)signal[i]=samples[Math.min(samples.length-1,Math.floor(i*step))];
 const sr=rate/step,frames=Math.max(0,Math.floor((signal.length-win)/hop));
 const rms=new Float32Array(frames),pitches=new Int16Array(frames),brightness=new Float32Array(frames);
 let maxR=0;
 for(let f=0;f<frames;f++){
  const pos=f*hop;let power=0,diff=0,high=0,low=0,prev=0;
  for(let i=0;i<win;i++){const v=signal[pos+i];power+=v*v;if(i){const d=v-prev;diff+=d*d;if(i%2===0)high+=Math.abs(d);else low+=Math.abs(v);}prev=v;}
  const level=Math.sqrt(power/win);rms[f]=level;maxR=Math.max(maxR,level);brightness[f]=diff/(power+1e-8);
 }
 const threshold=Math.max(.002,maxR*(.04+.018*(11-sensitivity)));
 if(kind==='drums'){
  const result=[];let last=-100;
  for(let f=2;f<frames-2;f++){
   const v=rms[f],prev=Math.max(rms[f-1],rms[f-2]);
   if(v<threshold||v<prev*(1.16-.008*sensitivity)||f-last<5)continue;
   const b=brightness[f],pitch=b<.18?36:b<.65?38:b<1.5?42:49;
   result.push({pitch,start:f*hop/sr,duration:.13,velocity:Math.round(Math.min(127,Math.max(35,95*v/(maxR||1))))});last=f;
  }
  return result;
 }
 const minHz=kind==='bass'?35:65,maxHz=kind==='bass'?520:1700;
 const minLag=Math.floor(sr/maxHz),maxLag=Math.min(win/2,Math.ceil(sr/minHz));
 for(let f=0;f<frames;f++){
  if(rms[f]<threshold)continue;
  const off=f*hop,measure=win-maxLag;let bestLag=0,best=Infinity;
  // normalized difference function, followed by local-minimum preference
  const values=new Float32Array(maxLag+1);
  for(let lag=minLag;lag<=maxLag;lag++){
   let sum=0,energy=0;
   for(let i=0;i<measure;i+=2){const x=signal[off+i],y=signal[off+i+lag];const d=x-y;sum+=d*d;energy+=x*x+y*y;}
   values[lag]=sum/(energy+1e-9);
  }
  for(let lag=minLag+1;lag<maxLag;lag++){
   if(values[lag]<best){best=values[lag];bestLag=lag;}
  }
  if(best>.33||!bestLag)continue;
  // Prefer the earliest credible periodicity to reduce octave-down errors.
  for(let lag=minLag+1;lag<bestLag;lag++)if(values[lag]<Math.min(.19,best*1.6)&&values[lag]<=values[lag-1]&&values[lag]<=values[lag+1]){bestLag=lag;break;}
  const midi=Math.round(69+12*Math.log2(sr/bestLag/440));
  if(midi>=24&&midi<=108)pitches[f]=midi;
 }
 const result=[];let start=-1,lastPitch=0,miss=0;
 const flush=(end)=>{if(start<0)return;const duration=(end-start)*hop/sr;if(duration>=.07){let sum=0,count=0;for(let i=start;i<end;i++)if(pitches[i]===lastPitch){sum+=rms[i];count++;}result.push({pitch:lastPitch,start:start*hop/sr,duration,velocity:Math.round(Math.max(30,Math.min(127,85*(sum/Math.max(1,count))/(maxR||1)+30)))});}start=-1;};
 for(let f=0;f<frames;f++){
  const p=pitches[f];
  if(!p){if(start>=0&&++miss>=3){flush(f-2);miss=0;}continue;}
  if(start<0){start=f;lastPitch=p;miss=0;continue;}
  if(p!==lastPitch){if(f-start>=3){flush(f);start=f;lastPitch=p;}else{lastPitch=p;} }
  miss=0;
 }
 flush(frames);
 return result;
}
function initTranscriber(){
 const status=$('transcribeStatus'),commit=$('transcribeCommit');
 $('transcribeAnalyze').onclick=async()=>{
  const file=$('transcribeFile').files?.[0];if(!file){status.textContent='音声を選択してください。';return;}
  transcriptionPending=null;commit.disabled=true;
  if(file.size>80*1024*1024){status.textContent='80MB以内の音声を選んでください。';return;}
  status.textContent='音声を解析中…（長い録音では時間がかかります）';
  await new Promise(r=>setTimeout(r,30));
  try{
   const c=ctx||(ctx=new AC()),buffer=await c.decodeAudioData(await file.arrayBuffer());
   if(buffer.duration>120)throw Error('現在の変換は120秒までです。音声を分割してください。');
   const mono=new Float32Array(buffer.length);
   for(let ch=0;ch<buffer.numberOfChannels;ch++){const channel=buffer.getChannelData(ch);for(let i=0;i<mono.length;i++)mono[i]+=channel[i]/buffer.numberOfChannels;}
   const kind=$('transcribeType').value,notes=transcribeMono(mono,buffer.sampleRate,kind,Number($('transcribeSensitivity').value));
   if(!notes.length)throw Error('音符を検出できませんでした。感度を上げるか、単音・ドラム単独の録音を試してください。');
   transcriptionPending={notes,kind,fileName:file.name};
   status.textContent=`${notes.length}音を検出しました。変換先：${NAMES[kind]}。解析結果は近似です。配置後にピアノロールで確認・修正してください。`;
   commit.disabled=false;
  }catch(e){status.textContent='変換失敗：'+e.message;console.warn(e);}
 };
 commit.onclick=()=>{
  if(!transcriptionPending)return;
  if(st.tracks.length>=18){status.textContent='トラック上限（18本）です。';return;}
  const {notes,kind,fileName}=transcriptionPending,base=$('transcribeStart').value==='zero'?0:st.playheadBeat;
  const track=makeTrack(kind,`${NAMES[kind]}（変換）`);
  track.notes=notes.filter(n=>base+n.start*st.bpm/60<MAX_BEATS).map(n=>({
   id:uid(),pitch:n.pitch,start:Number((base+n.start*st.bpm/60).toFixed(4)),
   duration:Number(clamp(n.duration*st.bpm/60,.125,32).toFixed(4)),velocity:n.velocity
  }));
  if(!track.notes.length){status.textContent='曲の最大拍数を超えています。';return;}
  st.tracks.push(track);st.selectedTrackId=track.id;selectedNotes.clear();
  checkpoint();render();status.textContent=`${track.notes.length}音を新しい${NAMES[kind]}トラックに配置しました。元音声は曲に追加していません。`;
  transcriptionPending=null;commit.disabled=true;
 };
}

function setupEvents(){initAutomation();initTranscriber();
 function noteFxApply(reset=false){const t=findTrack();if(!t||isAudio(t)||isGuide(t)||!selectedNotes.size){toast('先に音符を選択してください');return;}
 const gain=reset?100:clamp($('noteFxGain').value,0,200),pan=reset?0:clamp($('noteFxPan').value,-100,100);
 for(const n of t.notes)if(selectedNotes.has(n.id))n.detail={...(n.detail||{}),gain,pan};
 checkpoint();render();toast(selectedNotes.size+'音に詳細ミックスを適用');}
 $('applyNoteFx').onclick=()=>noteFxApply(false);
 $('resetNoteFx').onclick=()=>noteFxApply(true);

 $('newProjectBtn').onclick=()=>{if(!confirm('新しい曲を始めます。現在の編集・取り込んだ音声は置き換えられます。先にバックアップしましたか？'))return;stop();st=blank();audioFiles.clear();audioBuffers.clear();selectedNotes.clear();history=[];histIndex=-1;checkpoint();syncControls();render();};$('helpBtn').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();
 $('backupBtn').onclick=()=>void backupProject();$('restoreBtn').onclick=()=>$('restoreFile').click();$('restoreFile').onchange=e=>{void restoreProject(e.target.files?.[0]);e.target.value='';};
 $('importMelodyBtn').onclick=()=>$('melodyFile').click();$('melodyFile').onchange=e=>{void importMelody(e.target.files?.[0]);e.target.value='';};
 $('importVoiceBtn').onclick=()=>$('voiceFile').click();$('voiceFile').onchange=e=>{void importAudio(e.target.files?.[0],'voice');e.target.value='';};
 $('importAudioBtn').onclick=()=>$('audioFile').click();$('audioFile').onchange=e=>{void importAudio(e.target.files?.[0],'audio');e.target.value='';};
 $('songTitle').onchange=e=>{st.title=e.target.value.trim().slice(0,80)||'新しい曲';checkpoint();};
 $('bpm').onchange=e=>{if(playback)pause();st.bpm=clamp(e.target.value,40,240);e.target.value=st.bpm;checkpoint();render();};
 $('beats').onchange=e=>{if(playback)pause();const prior=st.beats;st.beats=Number(e.target.value);for(const s of st.sections){const count=Math.max(1,Math.round(s.lengthBeats/prior));s.lengthBeats=count*st.beats;}let cursor=0;for(const s of st.sections){s.startBeat=cursor;cursor+=s.lengthBeats;}checkpoint();render();};
 for(const [field,id] of [['guideAudible','guideAudible'],['guideInMix','guideInMix'],['voiceGuideMelody','voiceGuideMelody'],['normalize','normalize']])$(id).onchange=e=>{st[field]=e.target.checked;checkpoint();render();};
 $('playBtn').onclick=()=>void start();$('stopBtn').onclick=()=>stop();$('seekBar').oninput=e=>{if(playback)pause();st.playheadBeat=clamp(Number(e.target.value)/100*totalBeats(),0,totalBeats());renderTime();renderArrangement();renderRoll();};$('seekBar').onchange=scheduleSave;
 $('addSectionBtn').onclick=addSection;$('editSectionBtn').onclick=openSectionDialog;$('deleteSectionBtn').onclick=deleteSection;$('autoArrangeBtn').onclick=()=>synthesizeArrangement(false);$('demoBtn').onclick=loadDemo;
 $('sectionForm').addEventListener('submit',e=>{e.preventDefault();applySection();});$('sectionCancel').onclick=()=>$('sectionDialog').close();
 $('addTrackBtn').onclick=()=>addTrack($('instrumentSelect').value);$('removeTrackBtn').onclick=removeTrack;
 $('arrZoom').oninput=e=>{st.arrZoom=Number(e.target.value);renderArrangement();};$('arrZoom').onchange=checkpoint;
 $('rollPanMode').onclick=toggleRollPan; $('rollLeftBtn').onclick=()=>scrollRollTime(-1); $('rollRightBtn').onclick=()=>scrollRollTime(1); $('rollPitchUp').onclick=()=>moveRollPitch(1); $('rollPitchDown').onclick=()=>moveRollPitch(-1); $('rollOctaves').onchange=e=>{rollVisibleOctaves=Number(e.target.value);renderRoll();};
 $('rollZoom').oninput=e=>{st.rollZoom=Number(e.target.value);renderRoll();};$('rollZoom').onchange=checkpoint;
 $('snapSelect').onchange=e=>{st.snap=Number(e.target.value);checkpoint();renderRoll();};
 $('multiSelectBtn').onclick=()=>{multiSelectMode=!multiSelectMode;syncMultiSelect();};syncMultiSelect();$('selectAllNotesBtn').onclick=()=>{const t=findTrack();if(!t||isAudio(t))return;selectedNotes=new Set((t.notes||[]).map(n=>n.id));render();};$('clearSelectionBtn').onclick=()=>{selectedNotes.clear();render();};$('toolSelect').onclick=()=>selectTool('select');$('toolDraw').onclick=()=>selectTool('draw');
 $('undoBtn').onclick=undo;$('redoBtn').onclick=redo;$('deleteNoteBtn').onclick=removeNotes;$('duplicateNoteBtn').onclick=duplicateNotes;
 $('velocity').oninput=e=>{const t=findTrack();for(const n of t?.notes||[])if(selectedNotes.has(n.id))n.velocity=Number(e.target.value);renderInspector();};$('velocity').onchange=()=>checkpoint();
 for(const b of document.querySelectorAll('[data-move]'))b.onclick=()=>nudge(b.dataset.move);
 arrCanvas.addEventListener('click',e=>{const r=arrCanvas.getBoundingClientRect(),x=(e.clientX-r.left)*arrCanvas.width/r.width,y=(e.clientY-r.top)*arrCanvas.height/r.height;const index=Math.floor((y-36)/66);if(index>=0&&index<st.tracks.length){st.selectedTrackId=st.tracks[index].id;selectedNotes.clear();}if(x>=0){if(playback)pause();st.playheadBeat=clamp(Math.round(x/st.arrZoom/st.snap)*st.snap,0,totalBeats());}render();scheduleSave();});
 rollCanvas.addEventListener('pointerdown',onRollDown);rollCanvas.addEventListener('pointermove',onRollMove);rollCanvas.addEventListener('pointerup',onRollUp);rollCanvas.addEventListener('pointercancel',onRollUp);
 rollCanvas.addEventListener('dblclick',addNoteDouble);
 document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable],dialog'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeNotes();return;}const actions={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};if(actions[e.key]){e.preventDefault();nudge(actions[e.key]);}if(e.code==='Space'){e.preventDefault();void start();}});
 for(const key of ['volume','pan','tone','reverb']){const el=$('mix'+key[0].toUpperCase()+key.slice(1));el.oninput=()=>{const t=findTrack();if(!t)return;t[key]=Number(el.value);renderMix();};el.onchange=()=>{checkpoint();renderTracks();};}
 $('exportVoiceBtn').onclick=()=>void exportVoice();$('exportInstrumentBtn').onclick=()=>void exportWave('instrument');$('exportFinalBtn').onclick=()=>void exportWave('final');
 window.addEventListener('beforeunload',()=>{if(playback)finishPlayback();});
}
